def dosya_def_listesi(dosya_adi):
    """Belirli bir dosyadaki tum deflerin adlarini dondurur."""
    return [d["ad"] for d in PROJE_PROJEKSIYONU.get(dosya_adi, {}).get("defs", [])]

def dosya_islemleri(dosya_adi):
    """Belirli bir dosyadaki tum class ve metod isimlerini dondurur."""
    sonuc = []
    for cls in PROJE_PROJEKSIYONU.get(dosya_adi, {}).get("classes", []):
        sonuc.append(cls["ad"])
        for m in cls.get("metodlar", []):
            sonuc.append(cls["ad"] + "." + m["ad"])
    return sonuc

def tum_defler():
    """Tum dosyalardaki tum defleri (dosya, ad) seklinde dondurur."""
    sonuc = []
    for dosya, icerik in PROJE_PROJEKSIYONU.items():
        for d in icerik.get("defs", []):
            sonuc.append((dosya, d["ad"], d["satir"]))
    return sonuc

